contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token, uint256 tokenId) public payable {
        require(true);

        (uint256 feeAmount, uint256 protocolFeeAmount) = c.flashFeeAndProtocolFee();
        uint256 flashFee = c.flashFee(token, tokenId);
        bool available = c.availableForFlashLoan(token, tokenId);

        bool ownerCallSucceeded = true;
        address observedOwner;
        try ERC721(token).ownerOf(tokenId) returns (address owner) {
            observedOwner = owner;
        } catch {
            ownerCallSucceeded = false;
        }

        bool expectedAvailable = ownerCallSucceeded && observedOwner == address(c);

        assert(
            flashFee == feeAmount + protocolFeeAmount &&
            available == expectedAvailable
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _baseToken, address _nft) public payable {
        require(true);

        c.initialize(_baseToken, _nft, 1e18, 1e18, 0, 0, bytes32(0), false, false);

        uint256 virtualBaseTokenReserves = c.virtualBaseTokenReserves();
        uint256 virtualNftReserves = c.virtualNftReserves();
        address baseToken = c.baseToken();

        uint256 exponent = baseToken == address(0) ? 18 : (36 - ERC20(baseToken).decimals());
        uint256 expectedPrice = (virtualBaseTokenReserves * (10 ** exponent)) / virtualNftReserves;

        uint256 price = c.price();

        assert(price == expectedPrice);
    }

    receive() external payable {}
}

